// ── src/lib/agent.js ──
// Builds the AI agent's system prompt (from prompts/agent-system.md + settings) and the per-turn
// prompt, and cleans the agent's reply for WhatsApp.
//
// The system prompt only changes when settings change, so it stays byte-identical between turns
// and can be served from the prompt cache. Anything that varies per turn (time, customer, orders,
// conversation) goes in the turn prompt.
//
// Inlined into n8n Code nodes; keep dependency-free.

const FACT_LABELS = {
  hours: 'Opening hours',
  delivery_areas: 'Delivery areas',
  delivery_fee: 'Delivery fee',
  delivery_time: 'Delivery time',
  storage: 'Storage',
  shelf_life: 'Shelf life',
  pickup: 'Pickup',
};

function agentMoney(amount, currency) {
  return `${currency || 'GHS'} ${Number(amount || 0).toFixed(2)}`;
}

function renderCatalog(catalog) {
  const c = catalog || {};
  const currency = (c.brand && c.brand.currency) || 'GHS';
  const lines = (c.variants || []).map((v) => {
    const parts = [v.ingredients ? `ingredients: ${v.ingredients}` : null, v.copy || null].filter(Boolean);
    return `- ${v.name}${parts.length ? `: ${parts.join('. ')}` : ''}`;
  });
  const sizes = (c.sizes || []).map((s) => `${s.label} ${agentMoney(s.price, currency)}`).join(' · ');
  lines.push(`Sizes and prices (same for every flavour): ${sizes}. Up to ${c.maxQty || 24} bottles per order.`);
  return lines.join('\n');
}

function renderFacts(business) {
  const b = business || {};
  const known = [];
  const unknown = [];
  for (const [key, label] of Object.entries(FACT_LABELS)) {
    if (b[key] === null || b[key] === undefined || b[key] === '') unknown.push(label.toLowerCase());
    else known.push(`- ${label}: ${b[key]}`);
  }
  for (const f of b.extra_faq || []) {
    if (f && f.q && f.a) known.push(`- ${f.q} ${f.a}`);
  }
  return {
    facts: known.length ? known.join('\n') : '- (none yet)',
    unknown: unknown.length ? unknown.join(', ') : 'nothing',
  };
}

function buildAgentSystem(template, settings) {
  const s = settings || {};
  const brand = s.brand || {};
  const momo = s.momo || {};
  const { facts, unknown } = renderFacts(s.business);
  const momoText = momo.number ? `${momo.number}, account name ${momo.name}` : 'details the team sends';
  const values = {
    BRAND_NAME: brand.name || 'the shop',
    BRAND_SHORT: brand.shortName || brand.name || 'the shop',
    CITY: brand.city || 'Accra',
    SITE_URL: brand.siteUrl || '',
    CATALOG: renderCatalog(s.catalog),
    BUSINESS_FACTS: facts,
    UNKNOWN_FACTS: unknown,
    MOMO: momoText,
  };
  return template.replace(/\{\{([A-Z_]+)\}\}/g, (m, key) => (key in values ? values[key] : m));
}

function describeOrder(o) {
  if (!o) return 'none';
  const items = (o.items || []).map((i) => `${i.qty} × ${i.variant} ${i.size}`).join(', ');
  return `${o.code}, ${items}, ${agentMoney(o.total, o.currency)}, status ${o.status}`;
}

function formatAccraTime(date) {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Africa/Accra', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit',
  }).format(date);
}

// state: crm.ingest_inbound output; pendingTexts: texts since the bot last replied; note: what a
// non-text message was (photo, location, button); transcript: crm.recent_transcript output.
function buildAgentPrompt({ state, pendingTexts, note, transcript, now }) {
  const c = (state && state.customer) || {};
  const name = c.display_name || c.name || c.profile_name || 'unknown';
  const history = (transcript || [])
    .map((m) => `${m.dir === 'in' ? 'customer' : 'you'}: ${String(m.body || '').replace(/\s+/g, ' ').slice(0, 500)}`)
    .join('\n');
  const incoming = [...(pendingTexts || [])];
  if (note) incoming.push(note);
  return [
    `Now: ${formatAccraTime(now ? new Date(now) : new Date())} (Accra time)`,
    `Customer: ${name}${c.wa_id ? ` (+${c.wa_id})` : ''}${state && state.is_new ? ', first time messaging us' : ''}`,
    `Their open order: ${describeOrder(state && state.open_order)}`,
    `Paid order waiting for a delivery location: ${describeOrder(state && state.awaiting_location_order)}`,
    '',
    'Recent conversation (oldest first):',
    history || '(no earlier messages)',
    '',
    'New message(s) from the customer:',
    '<customer_message>',
    incoming.join('\n') || '(empty)',
    '</customer_message>',
  ].join('\n');
}

// Returns the text to send, or null when nothing should be sent.
function cleanAgentReply(output) {
  let text = String(output == null ? '' : output).trim();
  if (!text || /^NO_REPLY\b/.test(text)) return null;
  text = text
    .replace(/\*\*(.+?)\*\*/g, '*$1*') // markdown bold → WhatsApp bold
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\s*NO_REPLY\s*$/, '')
    .trim();
  return text || null;
}

// ── node logic ──
const { state, settings } = $('Start').first().json;
const customer = state.customer;
let text = cleanAgentReply($input.first().json.output);
if (text && state.is_new) text += '\n\n' + copy.aiDisclosure(settings.brand || {});
const payloads = text ? [waText(waRecipientOf(customer), text)] : [];
return [{ json: waSendRequest(customer, payloads, null, settings) }];

// ── src/lib/wa.js ──
// WhatsApp Cloud API outbound message payloads (POST /{phone-number-id}/messages).
// Limits enforced here so a long customer name or AI reply can't make Meta reject the message.
//
// Inlined into n8n Code nodes; keep dependency-free.

const WA_LIMITS = { text: 4096, interactiveBody: 1024, buttonTitle: 20, buttonId: 256, footer: 60, header: 60, caption: 1024 };

function clip(value, max) {
  const s = String(value == null ? '' : value);
  return s.length <= max ? s : `${s.slice(0, max - 1).trimEnd()}…`;
}

// `to` (phone) wins when both are present; `recipient` carries a business-scoped user ID for
// customers who hide their number behind a WhatsApp username.
function waRecipient(r) {
  if (r && r.wa_id) return { to: String(r.wa_id) };
  if (r && r.bsuid) return { recipient: String(r.bsuid) };
  throw new Error('Recipient has neither wa_id nor bsuid');
}

function waBase(r) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', ...waRecipient(r) };
}

function waText(r, body, options) {
  return { ...waBase(r), type: 'text', text: { body: clip(body, WA_LIMITS.text), preview_url: Boolean(options && options.previewUrl) } };
}

// buttons: [{id, title}] (max 3). header: {text} or {imageId}.
function waButtons(r, body, buttons, options) {
  const opts = options || {};
  const interactive = {
    type: 'button',
    body: { text: clip(body, WA_LIMITS.interactiveBody) },
    action: {
      buttons: (buttons || []).slice(0, 3).map((b) => ({
        type: 'reply',
        reply: { id: clip(b.id, WA_LIMITS.buttonId), title: clip(b.title, WA_LIMITS.buttonTitle) },
      })),
    },
  };
  if (opts.header && opts.header.imageId) interactive.header = { type: 'image', image: { id: opts.header.imageId } };
  else if (opts.header && opts.header.text) interactive.header = { type: 'text', text: clip(opts.header.text, WA_LIMITS.header) };
  if (opts.footer) interactive.footer = { text: clip(opts.footer, WA_LIMITS.footer) };
  return { ...waBase(r), type: 'interactive', interactive };
}

function waLocationRequest(r, body) {
  return {
    ...waBase(r),
    type: 'interactive',
    interactive: {
      type: 'location_request_message',
      body: { text: clip(body, WA_LIMITS.interactiveBody) },
      action: { name: 'send_location' },
    },
  };
}

function waImage(r, mediaId, caption) {
  const image = { id: mediaId };
  if (caption) image.caption = clip(caption, WA_LIMITS.caption);
  return { ...waBase(r), type: 'image', image };
}

// components: raw Cloud API template components (header/body/button parameters).
function waTemplate(r, name, language, components) {
  return { ...waBase(r), type: 'template', template: { name, language: { code: language || 'en' }, components: components || [] } };
}

function waTemplateText(value) {
  // Template parameters can't contain newlines, tabs or more than four consecutive spaces.
  return { type: 'text', text: clip(String(value == null ? '' : value).replace(/[\n\t]+/g, ' ').replace(/ {4,}/g, '   '), 1024) };
}

// Marks the customer's message as read and shows "typing…" until the reply is sent (max ~25 s).
function waTyping(messageId) {
  return { messaging_product: 'whatsapp', status: 'read', message_id: messageId, typing_indicator: { type: 'text' } };
}

function waRecipientOf(customer) {
  return { wa_id: (customer && customer.wa_id) || null, bsuid: (customer && customer.bsuid) || null };
}

// Input for the "WA · Send" sub-workflow: free-form payloads when the recipient's 24-hour window
// is open, otherwise the template (or nothing, if there is none).
function waSendRequest(customer, payloads, template, settings, ref) {
  return {
    customer_id: customer.id,
    window_open: customer.window_open !== false,
    payloads: payloads || [],
    template: template || null,
    whatsapp: (settings && settings.whatsapp) || {},
    // a failed send (expired token, blocked number…) alerts the developer straight away
    alert_url: (settings && settings.alerts && settings.alerts.webhook_url) || null,
    ref: ref === undefined ? null : ref,
  };
}

// Short human-readable version of an outbound payload for the conversation log.
function waLogBody(payload) {
  if (!payload) return '';
  switch (payload.type) {
    case 'text':
      return payload.text.body;
    case 'interactive':
      return (payload.interactive.body && payload.interactive.body.text) || `[${payload.interactive.type}]`;
    case 'image':
      return `[image] ${(payload.image && payload.image.caption) || ''}`.trim();
    case 'template':
      return `[template ${payload.template.name}]`;
    default:
      return `[${payload.type}]`;
  }
}

